begin;
create type public.certificate_correction_status as enum('pending','approved','rejected');
create table public.certificate_correction_requests(id uuid primary key,certificate_id uuid not null references public.participation_certificates(id),participant_id uuid not null references public.profiles(id),requested_name text not null check(char_length(requested_name) between 5 and 100),reason text not null check(char_length(reason) between 5 and 300),status public.certificate_correction_status not null default 'pending',reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create unique index certificate_correction_one_pending on public.certificate_correction_requests(certificate_id) where status='pending';
alter table public.certificate_correction_requests enable row level security;
create policy correction_read_own_admin on public.certificate_correction_requests for select to authenticated using(participant_id=auth.uid() or public.is_global_admin());
revoke all on public.certificate_correction_requests from anon,authenticated;grant select on public.certificate_correction_requests to authenticated;
create function public.request_certificate_name_correction(requested_id uuid,target_certificate_id uuid,desired_name text,request_reason text) returns uuid language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.participation_certificates where id=target_certificate_id and participant_id=auth.uid()) then raise exception 'CERTIFICATE_NOT_FOUND' using errcode='42501';end if;if char_length(btrim(desired_name)) not between 5 and 100 or char_length(btrim(request_reason)) not between 5 and 300 then raise exception 'INVALID_CORRECTION_REQUEST' using errcode='22023';end if;insert into public.certificate_correction_requests(id,certificate_id,participant_id,requested_name,reason)values(requested_id,target_certificate_id,auth.uid(),btrim(desired_name),btrim(request_reason));return requested_id;end $$;
create function public.get_admin_certificate_corrections() returns table(request_id uuid,certificate_id uuid,current_name text,requested_name text,reason text,status public.certificate_correction_status,created_at timestamptz) language plpgsql stable security definer set search_path='' as $$ begin if not public.is_global_admin() then raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';end if;return query select r.id,r.certificate_id,c.participant_name,r.requested_name,r.reason,r.status,r.created_at from public.certificate_correction_requests r join public.participation_certificates c on c.id=r.certificate_id order by r.status,r.created_at;end $$;
create function public.review_certificate_correction(target_request_id uuid,approve boolean,new_verification_code uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare r public.certificate_correction_requests;begin if not public.is_global_admin() then raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';end if;select * into r from public.certificate_correction_requests where id=target_request_id and status='pending' for update;if r is null then return false;end if;update public.certificate_correction_requests set status=case when approve then 'approved'::public.certificate_correction_status else 'rejected'::public.certificate_correction_status end,reviewed_by=auth.uid(),reviewed_at=now() where id=r.id;if approve then update public.participation_certificates set participant_name=r.requested_name,verification_code=new_verification_code,issued_at=now(),revoked_at=null where id=r.certificate_id;end if;return true;end $$;
create function public.get_admin_mission_quality_ranking(target_class_id uuid default null,period_days integer default 30) returns table(mission_title text,response_count bigint,average_helpful numeric,average_clarity numeric,issue_count bigint,needs_review boolean) language plpgsql stable security definer set search_path='' as $$ begin if not public.is_global_admin() then raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';end if;if period_days not between 1 and 365 then raise exception 'INVALID_PERIOD' using errcode='22023';end if;return query select m.title,count(*),round(avg(f.helpful),2),round(avg(f.clarity),2),count(*)filter(where not f.issue_codes=array['none']::text[]),(avg(f.helpful)<3.5 or avg(f.clarity)<3.5 or count(*)filter(where not f.issue_codes=array['none']::text[])>count(*)/2) from public.mission_quality_feedback f join public.class_mission_assignments a on a.id=f.assignment_id join public.mission_versions v on v.id=a.mission_version_id join public.missions m on m.id=v.mission_id where(target_class_id is null or f.class_id=target_class_id)and f.created_at>=now()-make_interval(days=>period_days) group by m.id,m.title order by needs_review desc,average_clarity,response_count desc;end $$;
create function public.get_admin_audit_timeline(period_days integer default 30) returns table(event_type text,description text,occurred_at timestamptz) language plpgsql stable security definer set search_path='' as $$ begin if not public.is_global_admin() then raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';end if;return query select e.action::text,'Ação administrativa protegida',e.occurred_at from public.admin_audit_events e where e.occurred_at>=now()-make_interval(days=>period_days) union all select 'certificate_revoked','Certificado revogado: '||h.reason,h.occurred_at from public.certificate_revocation_history h where h.occurred_at>=now()-make_interval(days=>period_days) union all select 'certificate_correction_'||r.status::text,'Correção de nome: '||r.status::text,coalesce(r.reviewed_at,r.created_at) from public.certificate_correction_requests r where coalesce(r.reviewed_at,r.created_at)>=now()-make_interval(days=>period_days) order by occurred_at desc;end $$;
revoke all on function public.request_certificate_name_correction(uuid,uuid,text,text),public.get_admin_certificate_corrections(),public.review_certificate_correction(uuid,boolean,uuid),public.get_admin_mission_quality_ranking(uuid,integer),public.get_admin_audit_timeline(integer) from public;
grant execute on function public.request_certificate_name_correction(uuid,uuid,text,text),public.get_admin_certificate_corrections(),public.review_certificate_correction(uuid,boolean,uuid),public.get_admin_mission_quality_ranking(uuid,integer),public.get_admin_audit_timeline(integer) to authenticated;
commit;
